def parse_price(text):
    match = re.search(r"([€£$])?\s*(\d[\d,.\s]*)", text or "")
    if not match:
        return Decimal(0), "EUR"
    digits = re.sub(r"[\s,.](?=\d{3}\b)", "", match[2].strip()).replace(",", ".").rstrip(".")
    return Decimal(digits), CURRENCIES.get(match[1], "EUR")


